    TableLayoutPanel ReviewPage(){var p=Page("5. Review and create a copy","An inspected ISO and your chosen Windows version.","Save a future plan, or create a separate ISO with an optional edition preference.");Help(preferEdition,"Writes a Retail edition preference for Home or Pro into the new copy only. Does not supply a license, activate Windows, remove editions, or apply your future goals. Existing setup configuration blocks this option.");p.Controls.Add(preferEdition);p.Controls.Add(TextLabel("Create ISO preserves all editions. It does not apply updates, drivers, app removal, languages or recovery changes. Retail preference does not provide a Windows license.","Only media copy, optional edition preference, and ISO mastering run in this version."));Field(p,"Your future plan",review,"Actual edition and requested broad goals. No operation executes; full details are available below.");var actions=Flow();actions.Controls.Add(export);actions.Controls.Add(build);var full=Button("Full plan explanation…");Help(full,"Read the complete untrimmed summary of source, goals, compatibility and limitations.");full.Click+=(_,_)=>ShowDetails("Full future-plan explanation",fullReview);actions.Controls.Add(full);p.Controls.Add(actions);Help(build,"Copy media to a new folder and create a separate ISO using Microsoft ADK Oscdimg. Pause/cancel wait for safe checkpoints; original media is untouched. Boot/install testing remains required.");Help(export,"Requires current inspection, selected edition and idle worker. Rehashes source before exporting nonexecuting JSON; no catalog operation applies.");p.Controls.Add(exportReason);p.Controls.Add(TextLabel("Not tested: whether packages, devices, startup, installation, recovery or apps will work. A saved plan is not a new Windows file.","These remain separate future verification gates. Unknown compatibility is not success."));return p;}
    void Go(int target){if(busy)return;if(target<0||target>4)return;if(target>0&&target!=3&&result==null){SetStatus("Choose and read an ISO first. Reference browsing without an ISO is available on step 1.");return;}step=target;ShowStep();}
    void ShowStep(){for(int i=0;i<pages.Count;i++)pages[i].Visible=i==step;count.Text=$"Step {step+1} of 5 — {Names[step]}";count.AccessibleDescription=count.Text;RefreshSummary();RefreshActions();}
    void RefreshActions(){for(int i=0;i<steps.Count;i++){steps[i].Enabled=!busy&&(i==0||i==3||result!=null);steps[i].Font=i==step?stepBold:Font;if(steps[i] is ShellButton selected){selected.Selected=i==step;selected.Invalidate();}}build.Enabled=!busy&&result!=null&&editions.SelectedItem is Edition;preferEdition.Enabled=!busy;browse.Enabled=!busy;inspect.Enabled=!busy&&source.Text.Length>0;editions.Enabled=!busy&&result!=null;foreach(var b in goals.Values)b.Enabled=!busy;back.Enabled=!busy&&step>0;next.Visible=step<4;next.Enabled=!busy&&result!=null&&editions.SelectedItem is Edition;undo.Enabled=!busy&&history.Count>0;export.Enabled=!busy&&result!=null&&resultPath!=null&&editions.SelectedItem is Edition;pause.Enabled=busy&&job!=null&&(!critical||job.IsPaused)&&!job.CancellationRequested;cancel.Enabled=busy&&job!=null&&(!critical||job.IsPaused)&&!job.CancellationRequested;reason.Text=busy?(job==null?(activity==Activity.PreparingInspection?"Choose a report folder or cancel this dialog. Inspection has not started.":"Exporting the plan. Wait for completion; pause/cancel are unavailable."):job.IsPaused?"Paused safely. Choose Resume or Cancel safely; required cleanup still completes.":critical?"Finishing verification and cleanup. Wait; no forced stop is available.":"Working on media. Pause/cancel take effect at safe checkpoints; selections are locked."):result==null?"Choose your Windows installation file and select Inspect ISO to continue. You can explore options first.":step==4?"Create ISO writes a separate copy. Future goals are not applied.":"Next keeps your selections and opens the following guided step.";exportReason.Text=busy?"Export unavailable while work is active.":result==null?"Save is unavailable: choose a file and select Inspect ISO first.":editions.SelectedItem is not Edition?"Save is unavailable: choose a Windows version in step 2.":"Ready for nonexecuting export; source identity is checked again.";reason.AccessibleDescription=reason.Text;exportReason.Accessi