    void SetStatus(string text,string? visible=null){fullStatus=text;statusDetails.Visible=true;if(status.Parent!=null)status.Parent.Visible=true;status.Text=visible??(text.Length<=135&&!text.Contains('\n')?text:text.Contains("failed",StringComparison.OrdinalIgnoreCase)||text.Contains("incomplete",StringComparison.OrdinalIgnoreCase)||text.Contains("error",StringComparison.OrdinalIgnoreCase)?"Operation needs attention. Open Full details for the error and recovery guidance.":text.StartsWith("Planning-only",StringComparison.OrdinalIgnoreCase)?"Future plan exported. Open Full details for its output path and limitations.":"Operation update available. Open Full details for the full message and paths.");status.AccessibleDescription=status.Text;statusDetails.Enabled=text.Length>0;}
    void Browse(){if(busy)return;using var d=new OpenFileDialog{Title="Choose a Windows installation file",Filter="Windows installation files (*.iso)|*.iso",CheckFileExists=true};if(d.ShowDialog(this)!=DialogResult.OK)return;source.Text=ShellGeometry.FullPathText(d.FileName);Invalidate("",false);}
    void Invalidate(string message,bool notify=true){result=null;resultPath=null;restoring=true;editions.Items.Clear();restoring=false;history.Clear();last=CaptureSelection();step=0;if(notify)SetStatus(message);else ClearStatus();ShowStep();}
    void CheckCurrent(){if(busy||result==null)return;try{var f=new FileInfo(source.Text);if(!f.Exists||f.Length!=bytes||f.LastWriteTimeUtc!=modified||!string.Equals(Path.GetFullPath(source.Text),result.Source,StringComparison.OrdinalIgnoreCase))Invalidate("Source changed or is unavailable. Old results cleared; read it again before exporting.");}catch(Exception e) when(e is IOException or UnauthorizedAccessException){Invalidate("Cannot confirm source identity. Check access and read it again before exporting.");}}
    string? NewFolder(string title){using var d=new FolderBrowserDialog{Description=title,UseDescriptionForTitle=true};return d.ShowDialog(this)==DialogResult.OK?Path.Combine(d.SelectedPath,"WinISOPilot-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")[..6]):null;}
