    async Task Export(){if(busy||result==null||resultPath==null||editions.SelectedItem is not Edition e)return;CheckCurrent();if(result==null||resultPath==null)return;activity=Activity.Exporting;busy=true;RefreshActions();try{string? folder=NewFolder("Choose a parent folder for a NEW future-plan export");if(folder==null)return;var c=new Choices(e.Index,goals["Updates"].Checked,goals["Drivers"].Checked,goals["Languages"].Checked,goals["Apps"].Checked,goals["Setup"].Checked,goals["WinRE"].Checked);string inspectedPath=resultPath;string file=await Task.Run(()=>Engine.Plan(inspectedPath,c,folder));SetStatus("Planning-only JSON exported: "+file+". Every requested operation remains NotImplemented and nonexecuting.");}catch(Exception ex){SetStatus("Plan export failed: "+ex.Message+". Check the source and output folder, then read the ISO again if identity changed.");}finally{busy=false;activity=Activity.Idle;CheckCurrent();ShowStep();}}
    Snapshot CaptureSelection()=>new(editions.SelectedItem is Edition e?e.Index:0,Keys.Select(k=>goals.TryGetValue(k,out var b)&&b.Checked).ToArray(),preferEdition.Checked);
    void ReconcileEditionText()
    {
        if(restoring||busy||result==null)return;
        if(editions.SelectedItem is Edition current&&editions.Text==current.Name)return;
        var exact=editions.Items.Cast<Edition>().Where(x=>x.Name==editions.Text).ToArray();
        if(exact.Length==1){editions.SelectedItem=exact[0];return;}
        restoring=true;editions.Text=editions.SelectedItem is Edition selected?selected.Name:"";restoring=false;
    }
    void Changed(){if(restoring||busy)return;var current=CaptureSelection();if(current.Index!=last.Index||!current.Goals.SequenceEqual(last.Goals)||current.PreferEdition!=last.PreferEdition){history.Add(last);if(history.Count>100)history.RemoveAt(0);last=current;}RefreshSummary();RefreshActions();}
    void Undo(){if(busy||history.Count==0)return;var previous=history[^1];history.RemoveAt(history.Count-1);restoring=true;for(int i=0;i<editions.Items.Count;i++)if(editions.Items[i] is Edition e&&e.Index==previous.Index)editions.SelectedIndex=i;for(int i=0;i<Keys.Length;i++)goals[Keys[i]].Checked=previous.Goals[i];preferEdition.Checked=previous.PreferEdition;restoring=false;last=CaptureSelection();RefreshSummary();RefreshActions();SetStatus("Previous edition, goals and setup preference restored. No source, Windows change, report or exported file was undone.");}
    void RefreshSummary(){if(result==null){summary.Text="No current completed inspection. Actual image metadata is unknown.";review.Text="Choose a Windows installation file and select Inspect ISO before saving a plan.";return;}var e=editions.SelectedItem as Edition;fullSummary=$"Editions observed: {result.Editions.Count}\r\nSelected edition: {e?.Name??"Not selected"} / index {e?.Index.ToString()??"Unknown"}\r\nVersion/build: {e?.Version??"Unknown"}\r\nArchitecture: {e?.Architecture??"Unknown"}\r\nLanguages: {(e?.Languages is {Count:>0} l?string.Join(", ",l):"Not returned by metadata provider")}\r\n\r\nSource identity: successful inspection required matching SHA-256 before/after. Not proof of Microsoft authenticity, malware safety, or successful installation.\r\nSHA-256: {result.SourceSha256}\r\nMetadata is container-self-reported, not verified by Microsoft.\r\nMetadata provider: {result.MetadataProvider}\r\nHandle result: {result.Cleanup}\r\nOwnership: {result.Ownership}\r\n\r\nCompatibility: {result.Compatibility}\r\nLocal tools: {string.Join("; ",result.Tools.Select(t=>t.Kind+" "+t.Version))}\r\n\r\nNotRun: packages/apps/drivers inventory, dependency checks, boot, installation, updates and recovery tests.";fullReview=$"Source: {Path.GetFileName(result.Source)}\r\nEdition: {e?.Name??"Not selected"} / index {e?.Index.ToString()??"Unknown"}\r\nVersion: {e?.Version??"Unknown"} / {e?.Architecture??"Unknown"}\r\nCompatibility: {result.Compatibility}\r\n\r\nBroad goals:\r\n"+string.Join("\r\n",Keys.Select(k=>$"• {k}: {(goals[k].Checked?"Requested — NotImplemented":"Not requested")}"))+$"\r\n\r\nSetup edition preference: {(preferEdition.Checked?"selected edition, Retail channel (no license provided)":"unchanged")}\r\nCatalog: reference families only; no additional choices selected.\r\nExport: nonexecuting JSON, not an ISO. No installation-media change occurs.\r\nAll servicing and installation verification remains NotRun.";summary.Text=$"Windows versions found: {result.Edi